public class Calculadora {
    public static int suma(int a, int b) { return a + b; }
    public static int resta(int a, int b) { return a - b; }
    public static int multiplicacion(int a, int b) { return a * b; }
    public static int division(int a, int b) {
        if (b == 0) {
            throw new ArithmeticException("Cannot divide by zero");
        }
        return a / b;
    }

    public static void main(String[] args) {
        int pasados = 0, fallidos = 0;

        if (suma(3, 4) == 7) { System.out.println("PASS: suma(3,4) = 7"); pasados++; }
        else { System.out.println("FAIL: suma(3,4) expected 7"); fallidos++; }

        if (suma(-2, 5) == 3) { System.out.println("PASS: suma(-2,5) = 3"); pasados++; }
        else { System.out.println("FAIL: suma(-2,5) expected 3"); fallidos++; }

        if (resta(10, 3) == 7) { System.out.println("PASS: resta(10,3) = 7"); pasados++; }
        else { System.out.println("FAIL: resta(10,3) expected 7"); fallidos++; }

        if (resta(2, 8) == -6) { System.out.println("PASS: resta(2,8) = -6"); pasados++; }
        else { System.out.println("FAIL: resta(2,8) expected -6"); fallidos++; }

        if (multiplicacion(4, 5) == 20) { System.out.println("PASS: multiplicacion(4,5) = 20"); pasados++; }
        else { System.out.println("FAIL: multiplicacion(4,5) expected 20"); fallidos++; }

        if (multiplicacion(-3, 7) == -21) { System.out.println("PASS: multiplicacion(-3,7) = -21"); pasados++; }
        else { System.out.println("FAIL: multiplicacion(-3,7) expected -21"); fallidos++; }

        if (division(10, 2) == 5) { System.out.println("PASS: division(10,2) = 5"); pasados++; }
        else { System.out.println("FAIL: division(10,2) expected 5"); fallidos++; }

        if (division(7, 2) == 3) { System.out.println("PASS: division(7,2) = 3"); pasados++; }
        else { System.out.println("FAIL: division(7,2) expected 3"); fallidos++; }

        try {
            division(5, 0);
            System.out.println("FAIL: division(5,0) should have thrown an exception"); fallidos++;
        } catch (ArithmeticException e) {
            System.out.println("PASS: division(5,0) throws ArithmeticException"); pasados++;
        }

        System.out.println("---");
        System.out.println("Results: " + pasados + " passed, " + fallidos + " failed");
    }
}

