public class CalculadoraCientifica {
    public static double suma(double a, double b) { return a + b; }
    public static double resta(double a, double b) { return a - b; }
    public static double multiplicacion(double a, double b) { return a * b; }
    public static double division(double a, double b) {
        if (b == 0) throw new ArithmeticException("Cannot divide by zero");
        return a / b;
    }
    public static double potencia(double base, double exponente) {
        return Math.pow(base, exponente);
    }
    public static double raizCuadrada(double numero) {
        if (numero < 0) throw new IllegalArgumentException("Cannot compute square root of a negative number: " + numero);
        return Math.sqrt(numero);
    }

    public static void main(String[] args) {
        int total = 0, pasados = 0, fallidos = 0;
        double epsilon = 0.0001;

        // Sum tests
        total++;
        if (Math.abs(suma(2.5, 3.5) - 6.0) < epsilon) { System.out.println("PASS: suma(2.5, 3.5) = 6.0"); pasados++; }
        else { System.out.println("FAIL: suma(2.5, 3.5) expected 6.0"); fallidos++; }

        total++;
        if (Math.abs(suma(0, 0) - 0) < epsilon) { System.out.println("PASS: suma(0, 0) = 0"); pasados++; }
        else { System.out.println("FAIL: suma(0, 0) expected 0"); fallidos++; }

        total++;
        if (Math.abs(suma(-5, 5) - 0) < epsilon) { System.out.println("PASS: suma(-5, 5) = 0"); pasados++; }
        else { System.out.println("FAIL: suma(-5, 5) expected 0"); fallidos++; }

        // Subtraction tests
        total++;
        if (Math.abs(resta(10, 3) - 7) < epsilon) { System.out.println("PASS: resta(10, 3) = 7"); pasados++; }
        else { System.out.println("FAIL: resta(10, 3) expected 7"); fallidos++; }

        total++;
        if (Math.abs(resta(0, 5) - (-5)) < epsilon) { System.out.println("PASS: resta(0, 5) = -5"); pasados++; }
        else { System.out.println("FAIL: resta(0, 5) expected -5"); fallidos++; }

        // Multiplication tests
        total++;
        if (Math.abs(multiplicacion(3, 4) - 12) < epsilon) { System.out.println("PASS: multiplicacion(3, 4) = 12"); pasados++; }
        else { System.out.println("FAIL: multiplicacion(3, 4) expected 12"); fallidos++; }

        total++;
        if (Math.abs(multiplicacion(0, 1000) - 0) < epsilon) { System.out.println("PASS: multiplicacion(0, 1000) = 0"); pasados++; }
        else { System.out.println("FAIL: multiplicacion(0, 1000) expected 0"); fallidos++; }

        total++;
        if (Math.abs(multiplicacion(-3, -3) - 9) < epsilon) { System.out.println("PASS: multiplicacion(-3, -3) = 9"); pasados++; }
        else { System.out.println("FAIL: multiplicacion(-3, -3) expected 9"); fallidos++; }

        // Division tests
        total++;
        if (Math.abs(division(10, 2) - 5) < epsilon) { System.out.println("PASS: division(10, 2) = 5"); pasados++; }
        else { System.out.println("FAIL: division(10, 2) expected 5"); fallidos++; }

        total++;
        if (Math.abs(division(7, 2) - 3.5) < epsilon) { System.out.println("PASS: division(7, 2) = 3.5"); pasados++; }
        else { System.out.println("FAIL: division(7, 2) expected 3.5"); fallidos++; }

        total++;
        try {
            division(5, 0);
            System.out.println("FAIL: division(5,0) should have thrown an exception"); fallidos++;
        } catch (ArithmeticException e) {
            System.out.println("PASS: division(5, 0) throws ArithmeticException"); pasados++;
        }

        // Power tests
        total++;
        if (Math.abs(potencia(2, 3) - 8) < epsilon) { System.out.println("PASS: potencia(2, 3) = 8"); pasados++; }
        else { System.out.println("FAIL: potencia(2, 3) expected 8"); fallidos++; }

        total++;
        if (Math.abs(potencia(5, 0) - 1) < epsilon) { System.out.println("PASS: potencia(5, 0) = 1"); pasados++; }
        else { System.out.println("FAIL: potencia(5, 0) expected 1"); fallidos++; }

        total++;
        if (Math.abs(potencia(2, -1) - 0.5) < epsilon) { System.out.println("PASS: potencia(2, -1) = 0.5"); pasados++; }
        else { System.out.println("FAIL: potencia(2, -1) expected 0.5"); fallidos++; }

        // Square root tests
        total++;
        if (Math.abs(raizCuadrada(9) - 3) < epsilon) { System.out.println("PASS: raizCuadrada(9) = 3"); pasados++; }
        else { System.out.println("FAIL: raizCuadrada(9) expected 3"); fallidos++; }

        total++;
        if (Math.abs(raizCuadrada(0) - 0) < epsilon) { System.out.println("PASS: raizCuadrada(0) = 0"); pasados++; }
        else { System.out.println("FAIL: raizCuadrada(0) expected 0"); fallidos++; }

        total++;
        if (Math.abs(raizCuadrada(2) - 1.4142) < 0.01) { System.out.println("PASS: raizCuadrada(2) ~ 1.4142"); pasados++; }
        else { System.out.println("FAIL: raizCuadrada(2) expected ~1.4142"); fallidos++; }

        total++;
        try {
            raizCuadrada(-4);
            System.out.println("FAIL: raizCuadrada(-4) should have thrown an exception"); fallidos++;
        } catch (IllegalArgumentException e) {
            System.out.println("PASS: raizCuadrada(-4) throws IllegalArgumentException"); pasados++;
        }

        // Final report
        System.out.println("==================================");
        System.out.println("TEST REPORT");
        System.out.println("Total: " + total);
        System.out.println("Passed: " + pasados);
        System.out.println("Failed: " + fallidos);
        System.out.println("Success rate: " + (pasados * 100 / total) + "%");
        System.out.println("==================================");
    }
}
